```{.r .cell-code}
# For reference
as.data.frame(rbind(
  cbind("elements", as.matrix(
    unique(faostat_total_emissions$`Element Code`)
  ), as.matrix(
    unique(faostat_total_emissions$Element)
  )),
  cbind("items", as.matrix(
    unique(faostat_total_emissions$`Item Code`)
  ), as.matrix(unique(
    faostat_total_emissions$`Item`
  )))
)) |>
  gt()
```

