::: {.cell}

```{.r .cell-code}
# Filter elements of interest
transformed_faostat_total <- faostat_total_emissions |>
  filter(
    `Item Code` %in% c(
      5061, 67292, 
      67291, 6751, 6750, 
      6795,  6993, 6992
    ),
    # `Item Code` %in% c(
    #   5064,  5060, 5066, 
    #   5058,  5059, 5063, 
    #   5062,  5061, 67292, 
    #   67291, 6751, 6750, 
    #   6795,  6993, 6992
    # ), 
    `Element Code` %in% c(
      724313, 724413,
      7273, 717815)
    ) |> 
  rename(
    `Driver Code` = `Item Code`,
    Driver = Item
  ) |> 
  mutate(
    `Sector Code` = 9999,
    Sector = "Undetermined",
    Sector = case_when(
      `Driver Code`== 5061 ~
      "Manufacture of fertilizers and nitrogen compounds",
      `Driver Code` %in% c(67291, 6795) ~
        "Undetermined from Agriculture",
      `Driver Code` %in% c(67292, 6750, 6751, 6992, 6993) ~
        "Undetermined from LULUCF",
      .default = Sector),
    `Sector Code` = case_when(
      `Driver Code`== 5061 ~
      2012,
      `Driver Code` %in% c(67291, 6795) ~
        9998,
      `Driver Code` %in% c(67292, 6750, 6751, 6992, 6993) ~
        9997,
      .default = `Sector Code`)
  ) |>
  # Finally select in order to 
  # bind to livestock and crops
  select(
    `Area Code`,
    Area,
    `Driver Code`,
    Driver,
    `Sector Code`,
    Sector,
    `Element Code`,
    Element,
    Year,
    Unit,
    Value
  )
```
