```{#lst-gwp-crops .r .cell-code  lst-cap="GWP calculation for crops"}
# Filter elements of interest
transformed_faostat_crops <- faostat_crops |> 
  filter(
    ! `Element Code` %in% c(
      5312, 5162, 516201, 516202,
      7245, 72303, 72430, 72440, 
      72342, 72343, 72362,
      723631, 723632, 72392
    ),
    `Item Code` != 1712
    # ! `Element Code` %in% c(
    #   5162, 516201, 516202,
    #   7245, 72430, 72440,
    #   72342, 72362,
    #   723631, 723632, 72392
    # )
    ) |> 
  # Global Warming Potential
  mutate(
    Value = case_when(
      `Element Code` %in% c(
        72255, 72257
      ) ~ Value * 28, # GWP CH4 AR5 100-year horizon
      `Element Code` %in% c(
        72302,72307
      ) ~ Value * 265 # GWP N2O AR5 100-year horizon
    )
  ) |> 
  mutate(
    temp_code = case_when(
      `Element Code` %in% c(
        72255, 72257
      ) ~ 724413,
      `Element Code` %in% c(
        72307, 72302
      ) ~ 724313,
      .default = NA
    ),
    temp = case_when(
      `Element Code` %in% c(
        72255, 72257
      ) ~ "Emissions (CO2eq) from CH4 (AR5)",
      `Element Code` %in% c(
        72307, 72302
      ) ~ "Emissions (CO2eq) from N2O (AR5)",
      .default = NA
    )
  ) |> 
  rename(
    `Sector Code` = `Item Code`,
    `Sector` = Item,
    `Driver Code` = `Element Code`,
    Driver = Element,
    `Element Code`= temp_code,
    Element = temp
  )|> 
  mutate(
    `Sector Code` = sprintf("%04d", `Sector Code`)
  ) |> 
  # Finally select in order to 
  # bind to livestock and crops
  select(
    `Area Code`,
    Area,
    `Driver Code`,
    Driver,
    `Sector Code`,
    Sector,
    `Element Code`,
    Element,
    Year,
    Unit,
    Value
  )
