```{#lst-gwp-animals .r .cell-code  lst-cap="GWP calculation for animals"}
# Filter elements of interest
transformed_faostat_livestock <- faostat_livestock |> 
  filter(
    ! `Element Code` %in% c(
      72380,  72381, 72386, 
      723601, 723602, 723611, 
      723612, 723801, 723802, 
      723811, 723812, 72340, 
      72341, 72346, 72360, 
      72361, 72366, 72431,
      72441
    ),
    ! `Item Code` %in% c(
      1757, 1759, 1760,
      1054, 2029, 1749,
      1048, 1755
    )) |>
  mutate(
    Value = case_when(
      `Element Code` %in% c(
        72254, 72256
      ) ~ Value * 28, # GWP CH4 AR5 100-year horizon
      `Element Code` %in% c(
        72300, 72301, 72306
      ) ~ Value * 265, # GWP N2O AR5 100-year horizon
      .default = Value
    )
  ) |> 
  mutate(
    temp_code = case_when(
      `Element Code` %in% c(
        72254, 72256
      ) ~ 724413,
      `Element Code` %in% c(
        72300, 72301, 72306
      ) ~ 724313,
       `Element Code` == 5111 ~ 5111,
      .default = NA
    ),
    temp = case_when(
      `Element Code` %in% c(
        72254, 72256
      ) ~ "Emissions (CO2eq) from CH4 (AR5)",
      `Element Code` %in% c(
        72300, 72301, 72306
      ) ~ "Emissions (CO2eq) from N2O (AR5)",
      `Element Code` == 5111 ~ "Number of animals",
      .default = NA
    )
  ) |> 
  rename(
    `Driver Code` = `Element Code`,
    Driver = Element,
    `Sector Code` = `Item Code`,
    Sector = Item,
    `Element Code`= temp_code,
    Element = temp
  )|>
  mutate(
    `Sector Code` = sprintf("%04d", `Sector Code`)
  ) |> 
  # Finally select in order to 
  # bind to livestock and crops
  select(
    `Area Code`,
    Area,
    `Driver Code`,
    Driver,
    `Sector Code`,
    Sector,
    `Element Code`,
    Element,
    Year,
    Unit,
    Value
  )
